text-align:center
}
body.item-view .widget.Header p{
text-align:center
}
.blog-name .widget.PageList{
padding:0
}
body.item-view .centered-top{
margin-bottom:5px
}
.search-action,.search-input{
margin-bottom:-8px
}
.search form{
margin-bottom:8px
}
body.item-view .subscribe-section-container{
margin:5px 0 0 0;
width:100%
}
#page_body.section div.widget.FeaturedPost,div.widget.PopularPosts{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container .post-outer{
padding:0
}
.post:first-child{
margin:0
}
.post-body .snippet-thumbnail{
margin:0 3vw 3vw 0
}
.post-body .snippet-thumbnail img{
height:20vw;
width:20vw;
max-height:128px;
max-width:128px
}
div.widget.PopularPosts div.item-thumbnail{
margin:0 3vw 3vw 0
}
div.widget.PopularPosts div.item-thumbnail img{
height:20vw;
width:20vw;
max-height:88px;
max-width:88px
}
.post-title{
line-height:1
}
.post-title,.post-title a{
font-size:20px
}
#page_body.section div.widget.FeaturedPost h3 a{
font-size:22px
}
.mobile-ad .inline-ad{
display:block
}
.page_body.has-vertical-ads .vertical-ad-container,.page_body.has-vertical-ads .vertical-ad-container ins{
display:none
}
.page_body.has-vertical-ads .centered .centered-bottom,.page_body.has-vertical-ads .centered .centered-top{
display:block;
width:auto
}
div.post-filter-message div{
padding:8px 16px
}
}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
body{
position:relative
}
body.item-view .blog-name{
margin-left:48px
}
.page_body{
margin-left:$(sidebar.width)
}
.search{
margin-left:0
}
.search.focused{
width:100%
}
.sticky{
padding-left:$(sidebar.width)
}
.hamburger-menu{
display:none
}
body.collapsed-header .page_body .centered-top-container{
padding-left:$(sidebar.width);
padding-right:0;
width:100%
}
body.collapsed-header .centered-top-container .search.focused{
width:100%
}
body.collapsed-header .centered-top-container .blog-name{
margin-left:0
}
body.collapsed-header.item-view .centered-top-container .search.focused{
width:calc(100% - 50px)
}
body.collapsed-header.item-view .centered-top-container .blog-name{
margin-left:40px
}
}
/* =========================================================
   QUESTTELLER
   Foundation Overrides v0.1
   ========================================================= */

:root {
  --qt-bg: #080a0c;
  --qt-surface: #101419;
  --qt-surface-raised: #151a20;

  --qt-text: #d8d3c7;
  --qt-text-muted: #8e918e;
  --qt-heading: #f0eadc;

  --qt-gold: #c59b52;
  --qt-plague: #7b9f58;
  --qt-undead: #667f8c;

  --qt-border: rgba(255, 255, 255, 0.09);

  --qt-reading-width: 760px;
  --qt-chapter-width: 980px;
  --qt-art-width: 900px;
  --qt-site-width: 1180px;

  --qt-radius: 8px;
}


/* ---------- Base ---------- */

html {
  background: var(--qt-bg);
}

body {
  background: var(--qt-bg);
  color: var(--qt-text);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    Helvetica,
    Arial,
    sans-serif;
}


/* ---------- Remove legacy Indie background ---------- */

.bg-photo-container,
.bg-photo-overlay {
  display: none !important;
}


/* ---------- Remove legacy sidebar layout ---------- */

.sidebar-container {
  display: none !important;
}

.vertical-ad-container {
  display: none !important;
}

body .page_body {
  margin-left: 0 !important;
}

body .sticky {
  padding-left: 0 !important;
}


/* ---------- Main application shell ---------- */

.page_body {
  background: var(--qt-bg);
}

.page_body .centered {
  box-sizing: border-box;
  max-width: var(--qt-site-width);
  margin: 0 auto;
  padding: 32px 24px 72px;
}


/* ---------- Header ---------- */

.centered-top-container {
  background: rgba(8, 10, 12, 0.96);
  border-bottom: 1px solid var(--qt-border);
  box-shadow: none;
}

.centered-top {
  max-width: var(--qt-site-width);
  margin: 0 auto;
}

.Header h1,
.Header h1 a,
.Header h1 a:hover,
.Header h1 a:visited {
  color: var(--qt-heading);
}

.Header p {
  color: var(--qt-text-muted);
}


/* ---------- Post surfaces ---------- */

#page_body .FeaturedPost,
.Blog .blog-posts .post-outer-container {
  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: var(--qt-radius);
  box-shadow: none;
}

.post-outer-container {
  margin-bottom: 24px;
}


/* ---------- Post titles ---------- */

.post-title {
  float: none;
  max-width: none;
  color: var(--qt-heading);
  line-height: 1.15;
}

.post-title,
.post-title a,
.post-title a:hover,
.post-title a:visited {
  color: var(--qt-heading);
}


/* ---------- Story body ---------- */

.post-body {
  color: var(--qt-text);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 18px;
  line-height: 1.8;
}

.post-body p {
  margin: 0 0 1.5em;
}

.post-body img {
  display: block;
  max-width: 100%;
  height: auto;
}


/* ---------- Single chapter ---------- */

body.item-view .Blog .post-outer {
  max-width: var(--qt-reading-width);
  margin-left: auto;
  margin-right: auto;
}

body.item-view .post-title {
  font-size: clamp(2.25rem, 6vw, 4.5rem);
  letter-spacing: -0.035em;
  line-height: 1;
  margin-bottom: 32px;
}


/* ---------- Links ---------- */

.post-body a {
  color: var(--qt-gold);
}

.post-body a:visited {
  color: var(--qt-gold);
}

.post-body a:hover {
  color: var(--qt-heading);
}


/* ---------- Labels ---------- */

.Label li,
.Label span.label-size,
.byline.post-labels a {
  background: var(--qt-surface-raised);
  border: 1px solid var(--qt-border);
  color: var(--qt-text-muted);
}


/* ---------- Comments ---------- */

#comments {
  border-top: 1px solid var(--qt-border);
  color: var(--qt-text);
}


/* ---------- Footer ---------- */

#footer {
  border-top: 1px solid var(--qt-border);
  color: var(--qt-text-muted);
  padding-top: 32px;
}


/* ---------- Mobile ---------- */

@media screen and (max-width: 800px) {

  .page_body .centered {
    padding-left: 12px;
    padding-right: 12px;
  }

  #page_body .FeaturedPost,
  .Blog .blog-posts .post-outer-container {
    border-radius: 0;
  }

  .post-body {
    font-size: 17px;
    line-height: 1.75;
  }

}
/* =========================================================
   QUESTTELLER HEADER
   ========================================================= */

.qt-site-header {
  position: relative;
  width: 100%;
  padding: 0;
  background:
    linear-gradient(
      180deg,
      rgba(12, 15, 18, 0.98) 0%,
      rgba(8, 10, 12, 0.98) 100%
    );
  border-bottom: 1px solid var(--qt-border);
}

.qt-header-inner {
  box-sizing: border-box;
  max-width: var(--qt-site-width);
  min-height: 86px;
  margin: 0 auto;
  padding: 14px 24px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}


/* ---------- Brand ---------- */

.qt-brand,
.qt-brand:hover,
.qt-brand:visited {
  display: flex;
  align-items: center;
  gap: 14px;

  color: var(--qt-heading);
  text-decoration: none;
}

.qt-brand-mark {
  display: grid;
  place-items: center;

  width: 46px;
  height: 46px;

  border: 1px solid rgba(197, 155, 82, 0.55);
  border-radius: 50%;

  color: var(--qt-gold);

  font-family: Georgia, serif;
  font-size: 24px;
  font-weight: 700;
  line-height: 1;

  background:
    radial-gradient(
      circle at center,
      rgba(197, 155, 82, 0.10),
      transparent 70%
    );

  box-shadow:
    0 0 24px rgba(197, 155, 82, 0.07);
}

.qt-brand-copy {
  display: flex;
  flex-direction: column;
}

.qt-brand-name {
  color: var(--qt-heading);

  font-size: 20px;
  font-weight: 700;
  line-height: 1.1;

  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.qt-brand-tagline {
  margin-top: 5px;

  color: var(--qt-text-muted);

  font-size: 11px;
  line-height: 1;

  letter-spacing: 0.08em;
  text-transform: uppercase;
}


/* ---------- Navigation ---------- */

.qt-main-nav {
  display: flex;
  align-items: center;
  gap: 6px;
}

.qt-main-nav a,
.qt-main-nav a:visited {
  position: relative;

  padding: 12px 14px;

  color: var(--qt-text-muted);

  font-size: 12px;
  font-weight: 600;

  letter-spacing: 0.08em;
  text-transform: uppercase;

  transition:
    color 160ms ease,
    background-color 160ms ease;
}

.qt-main-nav a:hover {
  color: var(--qt-heading);

  background: rgba(255, 255, 255, 0.035);
}


/* ---------- Kill old Indie header ---------- */

.qt-site-header > .centered-top {
  display: none !important;
}


/* ---------- Mobile header ---------- */

@media screen and (max-width: 700px) {

  .qt-header-inner {
    min-height: auto;
    padding: 14px 18px;

    flex-direction: column;
    align-items: stretch;

    gap: 14px;
  }

  .qt-brand {
    justify-content: center;
  }

  .qt-main-nav {
    justify-content: center;
    border-top: 1px solid var(--qt-border);
    padding-top: 8px;
  }

  .qt-main-nav a {
    flex: 1;
    text-align: center;
    padding: 10px 6px;
  }

}

.blog-name {
  margin: 0 !important;
}

.centered-top-placeholder {
  display: none !important;
}

body.item-view .blog-name,
body.item-view .centered-top {
  margin: 0 !important;
}
/* =========================================================
   QUESTTELLER HOMEPAGE
   ========================================================= */


/* ---------------------------------------------------------
   Featured / latest chapter
   --------------------------------------------------------- */

#page_body .FeaturedPost {
  padding: 0;
  overflow: hidden;
  background: transparent;
  border: 0;
}

.FeaturedPost .widget-content {
  padding: 0;
}

.qt-featured-chapter {
  overflow: hidden;

  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 10px;
}

.qt-featured-image {
  position: relative;

  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;

  overflow: hidden;

  background: #050607;
}

.qt-featured-image img {
  display: block;

  width: 100%;
  height: auto;

  object-fit: contain;
  object-position: center;

  transition: transform 500ms ease;
}

.qt-featured-image:hover img {
  transform: scale(1.015);
}

.qt-featured-content {
  max-width: 820px;

  padding: 40px 44px 44px;
}

.qt-featured-kicker {
  margin-bottom: 12px;

  color: var(--qt-gold);

  font-size: 11px;
  font-weight: 700;

  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.qt-featured-title {
  margin: 0 0 20px;

  color: var(--qt-heading);

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  font-size: clamp(2rem, 4vw, 3.6rem);
  font-weight: 750;
  line-height: 1.05;

  letter-spacing: -0.035em;
}

.qt-featured-title a,
.qt-featured-title a:visited {
  color: inherit;
}

.qt-featured-title a:hover {
  color: var(--qt-gold);
}

.qt-featured-summary {
  color: var(--qt-text-muted);

  font-family: Georgia, "Times New Roman", serif;
  font-size: 17px;
  line-height: 1.75;
}

.qt-featured-summary .snippet-container {
  max-height: none;
}

.qt-featured-summary .snippet-fade {
  display: none;
}

.qt-read-chapter {
  display: inline-flex;
  align-items: center;
  gap: 10px;

  margin-top: 28px;

  color: var(--qt-gold) !important;

  font-size: 12px;
  font-weight: 700;

  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.qt-read-chapter:hover {
  color: var(--qt-heading) !important;
}


/* ---------------------------------------------------------
   Chapter list
   --------------------------------------------------------- */

.Blog .blog-posts {
  display: grid;
  gap: 20px;

  margin-top: 28px;
}


/* Remove the old Blogger card around our card */

.Blog .blog-posts .post-outer-container {
  padding: 0;

  background: transparent;
  border: 0;
  border-radius: 0;
}


/* Our card */

.qt-chapter-card {
  display: grid;
  grid-template-columns: minmax(250px, 38%) 1fr;

  overflow: hidden;

  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 8px;

  transition:
    border-color 180ms ease,
    transform 180ms ease,
    background-color 180ms ease;
}

.qt-chapter-card:hover {
  transform: translateY(-2px);

  background: var(--qt-surface-raised);
  border-color: rgba(197, 155, 82, 0.25);
}


/* Image */

.qt-chapter-card-image {
  display: block;

  min-height: 240px;

  overflow: hidden;

  background: #050607;
}

.qt-chapter-card-image img {
  display: block;

  width: 100%;
  height: 100%;

  min-height: 240px;

  object-fit: cover;

  transition: transform 400ms ease;
}

.qt-chapter-card:hover .qt-chapter-card-image img {
  transform: scale(1.025);
}


/* Text */

.qt-chapter-card-content {
  display: flex;
  flex-direction: column;

  padding: 30px 34px;
}

.qt-chapter-card-kicker {
  margin-bottom: 10px;

  color: var(--qt-gold);

  font-size: 10px;
  font-weight: 700;

  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.qt-chapter-card-title {
  margin: 0 0 16px;

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  font-size: clamp(1.4rem, 2vw, 2rem);
  line-height: 1.15;

  letter-spacing: -0.025em;
}

.qt-chapter-card-title a,
.qt-chapter-card-title a:visited {
  color: var(--qt-heading);
}

.qt-chapter-card-title a:hover {
  color: var(--qt-gold);
}


/* Snippet */

.qt-chapter-card-summary {
  flex: 1;

  color: var(--qt-text-muted);

  font-family: Georgia, "Times New Roman", serif;
  font-size: 15px;
  line-height: 1.65;
}

.qt-chapter-card-summary .snippet-container {
  max-height: 100px;
}

.qt-chapter-card-summary .snippet-fade {
  display: none;
}


/* CTA */

.qt-chapter-card-link,
.qt-chapter-card-link:visited {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  align-self: flex-start;

  margin-top: 22px;

  color: var(--qt-gold);

  font-size: 11px;
  font-weight: 700;

  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.qt-chapter-card-link:hover {
  color: var(--qt-heading);
}


/* ---------------------------------------------------------
   Kill unwanted Blogger stream UI
   --------------------------------------------------------- */

body:not(.item-view) .post-bottom,
body:not(.item-view) .post-header,
body:not(.item-view) .post-share-buttons,
body:not(.item-view) .byline,
body:not(.item-view) .jump-link {
  display: none !important;
}

body:not(.item-view) #page_body {
  margin-top: 24px;
}


/* ---------------------------------------------------------
   Mobile
   --------------------------------------------------------- */

@media screen and (max-width: 700px) {

  .qt-featured-content {
    padding: 28px 22px 32px;
  }

  .qt-featured-title {
    font-size: 2rem;
  }

  .qt-chapter-card {
    grid-template-columns: 1fr;
  }

  .qt-chapter-card-image {
    min-height: auto;
  }

  .qt-chapter-card-image img {
    min-height: auto;

    aspect-ratio: 16 / 9;
  }

  .qt-chapter-card-content {
    padding: 24px 22px 28px;
  }

}

/* =========================================================
   QUESTTELLER CHAPTER READING EXPERIENCE
   ========================================================= */


/* ---------- Remove Blogger card treatment ---------- */

body.item-view .Blog .blog-posts .post-outer-container {
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 0;
}

body.item-view .Blog .post-outer {
  max-width: none;
}


/* ---------- Chapter shell ---------- */

.qt-single-post {
  width: 100%;
}

.qt-chapter-header {
  max-width: 900px;
  margin: 48px auto 56px;
  text-align: center;
}

.qt-chapter-kicker {
  margin-bottom: 18px;

  color: var(--qt-gold);

  font-size: 11px;
  font-weight: 700;

  letter-spacing: 0.18em;
  text-transform: uppercase;
}


/* ---------- Main chapter title ---------- */

body.item-view .qt-chapter-header .post-title {
  float: none;

  max-width: none;
  margin: 0;

  color: var(--qt-heading);

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  font-size: clamp(2.8rem, 7vw, 5.8rem);
  font-weight: 750;

  line-height: 0.98;

  letter-spacing: -0.045em;
}

body.item-view .qt-chapter-header .post-title a,
body.item-view .qt-chapter-header .post-title a:visited {
  color: inherit;
}


/* ---------- Metadata ---------- */

.qt-chapter-meta {
  margin-top: 22px;

  color: var(--qt-text-muted);

  font-size: 11px;

  letter-spacing: 0.07em;
  text-transform: uppercase;
}


/* ---------- Reading column ---------- */

.qt-chapter-reading {
  width: 100%;
  max-width: var(--qt-chapter-width);
  margin-left: auto;
  margin-right: auto;
}

.qt-chapter-reading .post-body {
  max-width: var(--qt-reading-width);

  margin: 0 auto;

  color: var(--qt-text);

  font-family: Georgia, "Times New Roman", serif;

  font-size: 19px;
  line-height: 1.9;
}

.qt-chapter-reading .post-body p {
  margin: 0 0 1.65em;
}


/* ---------- First paragraph ---------- */

.qt-chapter-reading .post-body > p:first-of-type::first-letter {
  float: left;

  margin: 0.08em 0.12em 0 0;

  color: var(--qt-gold);

  font-family: Georgia, serif;
  font-size: 4.2em;
  line-height: 0.78;
}


/* ---------- Scene headings ---------- */

.qt-chapter-reading h2 {
  margin: 4.5rem 0 1.5rem;

  color: var(--qt-heading);

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  font-size: clamp(1.7rem, 4vw, 2.5rem);
  line-height: 1.1;

  letter-spacing: -0.025em;
}

.qt-chapter-reading h3 {
  margin: 3rem 0 1rem;

  color: var(--qt-gold);

  font-size: 13px;
  font-weight: 700;

  letter-spacing: 0.13em;
  text-transform: uppercase;
}


/* =========================================================
   QUESTTELLER STORY ART
   ========================================================= */

.qt-art {
  width: min(var(--qt-art-width), calc(100vw - 48px));

  margin-top: 3.5rem;
  margin-right: 0;
  margin-bottom: 3.5rem;
  margin-left: 50%;

  transform: translateX(-50%);

  text-align: center;
}

.qt-art img {
  display: block;

  width: 100%;
  height: auto;

  border: 1px solid var(--qt-border);
  border-radius: 6px;
}

.qt-art figcaption {
  max-width: 720px;

  margin: 12px auto 0;

  color: var(--qt-text-muted);

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  font-size: 12px;
  line-height: 1.5;
}


/* ---------- Wide image ---------- */

.qt-art-wide {
  width: min(var(--qt-art-width), calc(100vw - 48px));
}


/* ---------- Cinematic full width ---------- */

.qt-art-full {
  width: min(1180px, calc(100vw - 32px));
}

.qt-art-full img {
  border-radius: 0;
}


/* ---------- Dramatic quote ---------- */

.qt-quote {
  max-width: 680px;

  margin: 4.5rem auto;

  padding: 34px 38px;

  border-top: 1px solid rgba(197, 155, 82, 0.35);
  border-bottom: 1px solid rgba(197, 155, 82, 0.35);

  color: var(--qt-heading);

  font-family: Georgia, serif;

  font-size: clamp(1.45rem, 3vw, 2.1rem);
  font-style: italic;
  line-height: 1.5;

  text-align: center;
}


/* ---------- Location ---------- */

.qt-location {
  margin: 4rem 0 1.5rem;

  color: var(--qt-gold);

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  font-size: 11px;
  font-weight: 700;

  letter-spacing: 0.16em;
  text-transform: uppercase;
}


/* ---------- Divider ---------- */

.qt-divider {
  display: flex;
  align-items: center;
  justify-content: center;

  gap: 18px;

  margin: 4.5rem auto;

  color: var(--qt-gold);
}

.qt-divider::before,
.qt-divider::after {
  content: "";

  display: block;

  width: 100px;
  height: 1px;

  background: var(--qt-border);
}


/* ---------- Chapter footer ---------- */

.qt-chapter-footer {
  max-width: var(--qt-reading-width);

  margin: 72px auto 0;

  padding-top: 32px;

  border-top: 1px solid var(--qt-border);
}


/* ---------- Mobile ---------- */

@media screen and (max-width: 700px) {

  .qt-chapter-header {
    margin: 32px auto 40px;
    padding: 0 10px;
  }

  body.item-view .qt-chapter-header .post-title {
    font-size: clamp(2.35rem, 12vw, 4rem);
  }

  .qt-chapter-reading .post-body {
    padding: 0 10px;

    font-size: 17px;
    line-height: 1.8;
  }

  .qt-art {
    margin-top: 2.5rem;
    margin-bottom: 2.5rem;
  }

  .qt-art-wide,
  .qt-art-full {
    width: 100vw;
  }

  .qt-art img {
    border-radius: 0;
  }

  .qt-quote {
    margin: 3rem 10px;
    padding: 26px 18px;
  }

}


/* =========================================================
   QUESTTELLER CHAPTER POLISH v0.2
   Balanced art, integrated footer, separate feature source
   ========================================================= */

/* ---------- Hidden source used only for Blogger featured image ---------- */

.qt-featured-source {
  display: none !important;
}


/* ---------- Keep the chapter on one coherent editorial grid ---------- */

body.item-view .qt-single-post {
  max-width: var(--qt-chapter-width);
  margin-left: auto;
  margin-right: auto;
}

body.item-view .qt-chapter-header {
  box-sizing: border-box;
  width: 100%;
  max-width: var(--qt-chapter-width);
  padding-left: 24px;
  padding-right: 24px;
}

body.item-view .qt-chapter-reading .post-body {
  box-sizing: border-box;
  width: 100%;
}


/* ---------- Single-post labels / share footer ---------- */

body.item-view .qt-chapter-footer {
  box-sizing: border-box;
  width: 100%;
  max-width: var(--qt-reading-width);
}

body.item-view .qt-chapter-footer .post-bottom {
  gap: 12px;
}

body.item-view .qt-chapter-footer .post-footer {
  color: var(--qt-text-muted);
}

body.item-view .qt-chapter-footer .byline.post-labels {
  display: block;
  width: 100%;
  margin: 0;
}

body.item-view .byline.post-labels a {
  margin: 4px 6px 4px 0;
  padding: 5px 10px;

  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 999px;

  color: var(--qt-text-muted);

  font-size: 11px;
  line-height: 1.4;

  transition:
    color 160ms ease,
    border-color 160ms ease,
    background-color 160ms ease;
}

body.item-view .byline.post-labels a:hover {
  color: var(--qt-gold);
  border-color: rgba(197, 155, 82, 0.35);
  background: var(--qt-surface-raised);
}


/* ---------- Comments: keep Blogger, visually integrate it ---------- */

body.item-view #comments {
  box-sizing: border-box;

  width: 100%;
  max-width: var(--qt-reading-width);

  margin: 52px auto 0;
  padding: 32px 0 0;

  background: transparent;

  border-top: 1px solid var(--qt-border);
}

body.item-view #comments .comments-content,
body.item-view #comments .comment-form,
body.item-view #comments .comment-footer {
  box-sizing: border-box;
  width: 100%;
}

body.item-view #comments .comment-form {
  overflow: hidden;

  margin-top: 18px;
  padding: 0;

  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: var(--qt-radius);
}

body.item-view #comment-editor {
  display: block;

  width: 100% !important;
  margin: 0;

  background: var(--qt-surface);

  /*
   * Blogger owns the contents of this cross-origin iframe.
   * This dark-mode filter keeps the embedded sign-in form from
   * appearing as a bright white panel inside the QuestTeller UI.
   */
  filter: invert(1) hue-rotate(180deg);
}


/* ---------- Remove the legacy Popular Posts block from chapters ---------- */

body.item-view .PopularPosts {
  display: none !important;
}


/* ---------- Site footer ---------- */

#footer {
  box-sizing: border-box;

  width: 100%;
  max-width: var(--qt-site-width);

  margin: 72px auto 0;
  padding: 34px 24px 12px;

  background: transparent;
  border-top: 1px solid var(--qt-border);

  color: var(--qt-text-muted);

  text-align: center;
}

#footer .widget-content {
  margin: 0 auto;
}

#footer .Attribution,
#footer .Attribution .widget-content,
#footer .Attribution .blogger {
  color: var(--qt-text-muted);
}

#footer a,
#footer a:visited {
  color: var(--qt-text-muted);
}

#footer a:hover {
  color: var(--qt-gold);
}

#footer .blogger {
  opacity: 0.72;
  font-size: 11px;
  letter-spacing: 0.05em;
}


/* ---------- Mobile polish ---------- */

@media screen and (max-width: 700px) {

  :root {
    --qt-reading-width: 100%;
    --qt-chapter-width: 100%;
    --qt-art-width: 100%;
  }

  body.item-view .qt-single-post {
    width: 100%;
  }

  body.item-view .qt-chapter-header {
    padding-left: 14px;
    padding-right: 14px;
  }

  .qt-chapter-reading .post-body {
    padding-left: 16px;
    padding-right: 16px;
  }

  .qt-art,
  .qt-art-wide,
  .qt-art-full {
    width: calc(100vw - 24px);
  }

  body.item-view #comments,
  body.item-view .qt-chapter-footer {
    width: calc(100% - 32px);
  }

  #footer {
    margin-top: 48px;
    padding-left: 16px;
    padding-right: 16px;
  }

}


/* =========================================================
   QUESTTELLER CHAPTER POLISH v0.3
   Tighter rhythm, story navigation, discussion and footer
   ========================================================= */

.qt-chapter-reading h2 {
  margin-top: 3.25rem;
  margin-bottom: 1.5rem;
}

.qt-divider {
  margin-top: 3.25rem;
  margin-bottom: 3.25rem;
}

.qt-art figcaption {
  max-width: 720px;
  margin: 14px auto 0;
  color: var(--qt-text-muted);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  font-size: 13px;
  font-style: italic;
  line-height: 1.55;
  letter-spacing: 0.01em;
}

/* ---------- End-of-chapter navigation ---------- */

.qt-chapter-nav {
  box-sizing: border-box;
  width: 100%;
  max-width: var(--qt-chapter-width);
  margin: 76px auto 0;
  padding: 36px 0 0;
  border-top: 1px solid var(--qt-border);
}

.qt-chapter-nav-heading {
  margin-bottom: 24px;
  text-align: center;
}

.qt-chapter-nav-kicker {
  display: block;
  color: var(--qt-gold);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}

.qt-chapter-nav-current {
  display: block;
  max-width: 680px;
  margin: 9px auto 0;
  color: var(--qt-heading);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 15px;
  line-height: 1.5;
}

.qt-chapter-nav-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: stretch;
  gap: 14px;
}

.qt-chapter-nav-card,
.qt-chapter-nav-card:visited {
  box-sizing: border-box;
  display: flex;
  min-height: 116px;
  padding: 20px 22px;
  flex-direction: column;
  justify-content: center;
  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: var(--qt-radius);
  color: var(--qt-heading);
  transition:
    transform 180ms ease,
    background-color 180ms ease,
    border-color 180ms ease;
}

.qt-chapter-nav-card:hover {
  transform: translateY(-2px);
  background: var(--qt-surface-raised);
  border-color: rgba(197, 155, 82, 0.35);
  color: var(--qt-heading);
}

.qt-chapter-nav-prev {
  text-align: left;
}

.qt-chapter-nav-next {
  text-align: right;
}

.qt-chapter-nav-direction {
  color: var(--qt-gold);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.qt-chapter-nav-title {
  margin-top: 10px;
  color: var(--qt-heading);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.35;
}

.qt-chapter-nav-home,
.qt-chapter-nav-home:visited {
  align-self: center;
  padding: 11px 14px;
  color: var(--qt-text-muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  white-space: nowrap;
}

.qt-chapter-nav-home:hover {
  color: var(--qt-gold);
}

.qt-chapter-nav-empty {
  min-height: 1px;
}

body.item-view .qt-chapter-footer {
  margin-top: 34px;
  padding-top: 0;
  border-top: 0;
}

/* ---------- Discussion ---------- */

body.item-view #comments {
  margin-top: 48px;
}

body.item-view #comments h3.title.qt-comments-title {
  position: static;
  clip: auto;
  display: block;
  width: auto;
  height: auto;
  margin: 0 0 18px;
  padding: 0;
  overflow: visible;
  color: var(--qt-heading);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.01em;
}

body.item-view #comments h3.title.qt-comments-title::before {
  content: "Chronicle ";
  color: var(--qt-gold);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

body.item-view #comments .comment-form {
  box-shadow: none;
}

/* ---------- QuestTeller footer identity ---------- */

#footer .qt-footer-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  width: 100%;
}

.qt-footer-brand {
  text-align: left;
}

.qt-footer-name {
  color: var(--qt-heading);
  font-size: 14px;
  font-weight: 750;
  line-height: 1.1;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.qt-footer-tagline {
  margin-top: 5px;
  color: var(--qt-text-muted);
  font-size: 11px;
  line-height: 1.4;
}

.qt-footer-links {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
}

.qt-footer-links a,
.qt-footer-links a:visited {
  color: var(--qt-text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.qt-footer-links a:hover {
  color: var(--qt-gold);
}

.qt-footer-platform {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  color: var(--qt-text-muted);
  font-size: 10px;
  line-height: 1.4;
  text-align: right;
}

.qt-footer-platform .blogger {
  display: inline-flex;
  align-items: center;
  margin: 0;
  opacity: 0.68;
}

.qt-footer-platform .blogger svg,
.qt-footer-platform .blogger img {
  width: 14px;
  height: 14px;
  margin-right: 6px;
}

.qt-footer-platform .copyright {
  margin: 0;
  font-size: inherit;
}

@media screen and (max-width: 700px) {
  .qt-chapter-reading h2 {
    margin-top: 2.75rem;
  }

  .qt-divider {
    margin-top: 2.75rem;
    margin-bottom: 2.75rem;
  }

  .qt-chapter-nav {
    width: calc(100% - 32px);
    margin-top: 56px;
    padding-top: 28px;
  }

  .qt-chapter-nav-grid {
    grid-template-columns: 1fr;
  }

  .qt-chapter-nav-empty {
    display: none;
  }

  .qt-chapter-nav-prev,
  .qt-chapter-nav-next {
    text-align: left;
  }

  .qt-chapter-nav-home {
    order: 3;
    justify-self: center;
  }

  #footer .qt-footer-content {
    flex-direction: column;
    align-items: center;
    text-align: center;
  }

  .qt-footer-brand,
  .qt-footer-platform {
    text-align: center;
  }

  .qt-footer-platform {
    justify-content: center;
    flex-wrap: wrap;
  }
}


/* =========================================================
   ALISANDER IDENTITY v0.4
   Character-first header and footer
   ========================================================= */

.qt-brand-mark.qt-brand-portrait {
  width: 54px;
  height: 54px;
  flex: 0 0 54px;

  border-radius: 9px;
  border: 1px solid rgba(197, 155, 82, 0.52);

  background-image:
    linear-gradient(rgba(8, 10, 12, 0.04), rgba(8, 10, 12, 0.20)),
    url('https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEi_3iXoLoBY3jFfcF0Qb5s5QZnb0btP9kXC-9OBtlbvV4a8rrro3J3VgMjtJ3hYVzEmGMbKQ6k2RD6vCD3tkfg79QnhihyQ7mZnyJRnoIaGA5GMt79j9s4wfUoFtf8uXDeb9k1trVkfez6-Pl8W4QrrZ1lkpH6qxgmG-Nw2xLFUu51ANNnn9jV8jV2zBBs/s1600/chapter-01-01-awakening.png');
  background-repeat: no-repeat;
  background-size: 245%;
  background-position: 36% 27%;

  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.40),
    0 0 24px rgba(197, 155, 82, 0.08);

  color: transparent;
  font-size: 0;
}

.qt-brand-name {
  font-size: 22px;
  letter-spacing: 0.10em;
}

.qt-brand-tagline {
  color: var(--qt-gold);
  opacity: 0.78;
  letter-spacing: 0.12em;
}

#footer .qt-footer-name {
  color: var(--qt-heading);
}

#footer .qt-footer-tagline {
  color: var(--qt-gold);
  opacity: 0.74;
}

#footer .qt-footer-platform {
  max-width: 260px;
}

#footer .qt-footer-platform .blogger {
  display: none !important;
}

@media screen and (max-width: 700px) {
  .qt-brand-mark.qt-brand-portrait {
    width: 50px;
    height: 50px;
    flex-basis: 50px;
  }

  .qt-brand-name {
    font-size: 20px;
  }

  .qt-brand-tagline {
    font-size: 10px;
  }
}


/* =========================================================
   ALISANDER JOURNEY ARCHITECTURE v0.5
   Homepage, Chronicles archive and character profile
   ========================================================= */

.qt-section-kicker {
  margin-bottom: 10px;
  color: var(--qt-gold);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.qt-primary-link,
.qt-primary-link:visited,
.qt-secondary-link,
.qt-secondary-link:visited {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.qt-primary-link,
.qt-primary-link:visited {
  color: var(--qt-gold);
}

.qt-primary-link:hover {
  color: var(--qt-heading);
}

.qt-secondary-link,
.qt-secondary-link:visited {
  color: var(--qt-text-muted);
}

.qt-secondary-link:hover {
  color: var(--qt-heading);
}

/* Current journey */

.qt-journey-overview {
  box-sizing: border-box;
  margin: 24px 0 28px;
  padding: 34px 36px;
  background:
    linear-gradient(120deg, rgba(197, 155, 82, 0.06), transparent 42%),
    var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 10px;
}

.qt-journey-overview-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(300px, 0.85fr);
  gap: 36px;
  align-items: stretch;
}

.qt-journey-overview-copy h2,
.qt-home-explore h2,
.qt-home-about h2,
.qt-chronicles-hero h1 {
  margin: 0;
  color: var(--qt-heading);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  letter-spacing: -0.035em;
}

.qt-journey-overview-copy h2 {
  font-size: clamp(2rem, 4vw, 3.35rem);
  line-height: 1;
}

.qt-journey-overview-copy p {
  max-width: 720px;
  margin: 18px 0 0;
  color: var(--qt-text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 16px;
  line-height: 1.75;
}

.qt-journey-location {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 22px;
  color: var(--qt-text-muted);
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.qt-journey-location strong {
  color: var(--qt-heading);
}

.qt-journey-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  margin-top: 28px;
}

.qt-journey-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.qt-journey-stat {
  min-height: 92px;
  padding: 16px;
  background: rgba(255, 255, 255, 0.018);
  border: 1px solid var(--qt-border);
  border-radius: 7px;
}

.qt-journey-stat-label {
  display: block;
  margin-bottom: 10px;
  color: var(--qt-text-muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.qt-journey-stat strong {
  color: var(--qt-heading);
  font-size: 14px;
  line-height: 1.35;
}

/* Journey map */

.qt-home-explore {
  margin-top: 52px;
  padding-top: 36px;
  border-top: 1px solid var(--qt-border);
}

.qt-home-explore h2 {
  font-size: clamp(1.8rem, 3vw, 2.6rem);
  line-height: 1.1;
}

.qt-explore-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 22px;
}

.qt-explore-card,
.qt-explore-card:visited {
  box-sizing: border-box;
  min-height: 150px;
  padding: 22px;
  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: var(--qt-radius);
  color: var(--qt-text-muted);
}

a.qt-explore-card {
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    background-color 180ms ease;
}

a.qt-explore-card:hover {
  transform: translateY(-2px);
  background: var(--qt-surface-raised);
  border-color: rgba(197, 155, 82, 0.32);
}

.qt-explore-card-active {
  background:
    linear-gradient(140deg, rgba(197, 155, 82, 0.08), transparent 55%),
    var(--qt-surface);
}

.qt-explore-status {
  display: block;
  margin-bottom: 18px;
  color: var(--qt-gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.qt-explore-card strong {
  display: block;
  margin-bottom: 8px;
  color: var(--qt-heading);
  font-size: 18px;
  line-height: 1.2;
}

.qt-explore-card > span:last-child {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 13px;
  line-height: 1.55;
}

/* About teaser */

.qt-home-about {
  display: grid;
  grid-template-columns: minmax(260px, 0.72fr) minmax(0, 1.28fr);
  gap: 36px;
  align-items: center;
  margin-top: 52px;
  padding: 28px;
  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 10px;
  overflow: hidden;
}

.qt-home-about-art {
  overflow: hidden;
  border-radius: 7px;
  background: #050607;
}

.qt-home-about-art img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  object-position: 50% 25%;
}

.qt-home-about h2 {
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1;
}

.qt-home-about-copy p {
  max-width: 650px;
  margin: 18px 0 24px;
  color: var(--qt-text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 16px;
  line-height: 1.75;
}

/* Chronicles archive */

.qt-chronicles-hero {
  margin: 24px 0 28px;
  padding: 34px 36px;
  background:
    linear-gradient(120deg, rgba(102, 127, 140, 0.08), transparent 42%),
    var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 10px;
}

.qt-chronicles-hero h1 {
  font-size: clamp(2.2rem, 5vw, 4rem);
  line-height: 1;
}

.qt-chronicles-hero p {
  max-width: 760px;
  margin: 18px 0 0;
  color: var(--qt-text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 16px;
  line-height: 1.75;
}

.qt-chronicles-current {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 14px;
  margin-top: 24px;
}

.qt-chronicles-current span {
  color: var(--qt-gold);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.qt-chronicles-current strong {
  color: var(--qt-heading);
  font-size: 14px;
}

body.label-view .post-filter-message {
  display: none;
}

/* Static page shell */

body.item-view .qt-page-post {
  box-sizing: border-box;
  width: 100%;
  max-width: var(--qt-chapter-width);
  margin: 0 auto;
}

.qt-page-header {
  max-width: 900px;
  margin: 48px auto 38px;
  padding: 0 24px;
  text-align: center;
}

body.item-view .qt-page-header .post-title {
  float: none;
  max-width: none;
  margin: 0;
  color: var(--qt-heading);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  font-size: clamp(2.8rem, 7vw, 5.4rem);
  font-weight: 750;
  line-height: 0.98;
  letter-spacing: -0.045em;
}

.qt-page-reading {
  width: 100%;
}

.qt-page-reading .post-body {
  max-width: var(--qt-chapter-width);
  margin: 0 auto;
}

/* About page */

.qt-about-page {
  width: 100%;
}

.qt-about-hero {
  display: grid;
  grid-template-columns: minmax(300px, 0.82fr) minmax(0, 1.18fr);
  gap: 42px;
  align-items: center;
}

.qt-about-portrait {
  margin: 0;
  overflow: hidden;
  background: #050607;
  border: 1px solid var(--qt-border);
  border-radius: 10px;
}

.qt-about-portrait img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 5;
  object-fit: cover;
  object-position: 50% 18%;
}

.qt-about-intro {
  padding-right: 10px;
}

.qt-about-name {
  margin: 0;
  color: var(--qt-heading);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 780;
  line-height: 0.95;
  letter-spacing: -0.05em;
}

.qt-about-role {
  margin-top: 12px;
  color: var(--qt-gold);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.qt-about-lede {
  margin: 22px 0 0 !important;
  color: var(--qt-text);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 19px;
  line-height: 1.8;
}

.qt-character-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 28px;
}

.qt-character-stat {
  padding: 14px;
  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 7px;
}

.qt-character-stat span {
  display: block;
  margin-bottom: 7px;
  color: var(--qt-text-muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.qt-character-stat strong {
  color: var(--qt-heading);
  font-size: 14px;
  line-height: 1.35;
}

.qt-about-section {
  margin-top: 60px;
  padding-top: 38px;
  border-top: 1px solid var(--qt-border);
}

.qt-about-section h2 {
  margin: 0 0 18px;
  color: var(--qt-heading);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  font-size: clamp(1.8rem, 4vw, 2.7rem);
  line-height: 1.08;
  letter-spacing: -0.03em;
}

.qt-about-section > p {
  max-width: 780px;
  color: var(--qt-text);
  font-size: 18px;
  line-height: 1.85;
}

.qt-level-card {
  margin-top: 26px;
  padding: 24px;
  background:
    linear-gradient(120deg, rgba(197, 155, 82, 0.07), transparent 48%),
    var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 9px;
}

.qt-level-card-header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: end;
}

.qt-level-card-header span {
  color: var(--qt-text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.qt-level-card-header strong {
  color: var(--qt-heading);
  font-size: 24px;
}

.qt-level-progress {
  height: 7px;
  margin-top: 18px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 999px;
}

.qt-level-progress-fill {
  height: 100%;
  background: var(--qt-gold);
  border-radius: inherit;
}

.qt-level-note {
  margin: 12px 0 0 !important;
  color: var(--qt-text-muted) !important;
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif !important;
  font-size: 11px !important;
  line-height: 1.5 !important;
}

.qt-roadmap {
  display: grid;
  gap: 12px;
  margin-top: 26px;
}

.qt-roadmap-item {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 22px;
  padding: 18px 0;
  border-bottom: 1px solid var(--qt-border);
}

.qt-roadmap-item:last-child {
  border-bottom: 0;
}

.qt-roadmap-stage {
  color: var(--qt-gold);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.qt-roadmap-copy strong {
  display: block;
  color: var(--qt-heading);
  font-size: 16px;
}

.qt-roadmap-copy span {
  display: block;
  margin-top: 6px;
  color: var(--qt-text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 14px;
  line-height: 1.55;
}

@media screen and (max-width: 800px) {
  .qt-journey-overview {
    padding: 26px 22px;
  }

  .qt-journey-overview-grid,
  .qt-home-about,
  .qt-about-hero {
    grid-template-columns: 1fr;
  }

  .qt-journey-stats,
  .qt-character-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .qt-explore-grid {
    grid-template-columns: 1fr;
  }

  .qt-home-about {
    padding: 20px;
  }

  .qt-home-about-art img {
    aspect-ratio: 16 / 9;
  }

  .qt-chronicles-hero {
    padding: 28px 22px;
  }

  .qt-page-header {
    margin-top: 34px;
  }

  .qt-about-intro {
    padding-right: 0;
  }

  .qt-roadmap-item {
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .qt-chapter-closing {
  text-align: center;
}
}

@media screen and (max-width: 520px) {
  .qt-journey-stats,
  .qt-character-grid {
    grid-template-columns: 1fr;
  }

  .qt-journey-actions {
    flex-direction: column;
    align-items: flex-start;
  }
}


/* =========================================================
   ALISANDER JOURNEY + CHARACTER DOSSIER v0.6
   Dedicated Journey page and tabletop-style character sheet
   ========================================================= */

/* ---------- Navigation expansion ---------- */

.qt-main-nav {
  flex-wrap: wrap;
}

.qt-section-row {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
}

.qt-section-row .qt-secondary-link {
  margin-bottom: 4px;
  white-space: nowrap;
}

/* =========================================================
   JOURNEY PAGE
   ========================================================= */

.qt-journey-page {
  width: 100%;
}

.qt-journey-hero {
  padding: 34px 36px;
  background:
    linear-gradient(120deg, rgba(197, 155, 82, 0.07), transparent 44%),
    var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 10px;
}

.qt-journey-hero h2 {
  margin: 0;
  color: var(--qt-heading);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  font-size: clamp(2.4rem, 6vw, 4.6rem);
  line-height: 0.98;
  letter-spacing: -0.045em;
}

.qt-journey-hero p {
  max-width: 780px;
  margin: 20px 0 0;
  color: var(--qt-text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 17px;
  line-height: 1.8;
}

.qt-journey-current-banner {
  display: grid;
  grid-template-columns: 120px minmax(0, 1fr) auto;
  gap: 22px;
  align-items: center;
  margin-top: 28px;
  padding-top: 24px;
  border-top: 1px solid var(--qt-border);
}

.qt-journey-current-banner > span {
  color: var(--qt-gold);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.qt-journey-current-banner strong {
  color: var(--qt-heading);
  font-size: 18px;
  line-height: 1.3;
}

.qt-journey-current-banner em {
  color: var(--qt-text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 13px;
  font-style: normal;
}

.qt-journey-section {
  margin-top: 58px;
  padding-top: 36px;
  border-top: 1px solid var(--qt-border);
}

.qt-journey-section h2 {
  margin: 0;
  color: var(--qt-heading);
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  font-size: clamp(1.9rem, 4vw, 2.9rem);
  line-height: 1.05;
  letter-spacing: -0.035em;
}

.qt-journey-section > p {
  max-width: 760px;
  margin: 16px 0 0;
  color: var(--qt-text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 16px;
  line-height: 1.75;
}

.qt-world-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 26px;
}

.qt-world-card {
  position: relative;
  min-height: 166px;
  padding: 22px;
  overflow: hidden;
  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 8px;
}

.qt-world-card-current {
  background:
    linear-gradient(140deg, rgba(197, 155, 82, 0.10), transparent 58%),
    var(--qt-surface);
  border-color: rgba(197, 155, 82, 0.30);
}

.qt-world-state {
  display: block;
  margin-bottom: 18px;
  color: var(--qt-gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.qt-world-card h3 {
  margin: 0;
  color: var(--qt-heading);
  font-size: 18px;
  line-height: 1.2;
}

.qt-world-card p {
  margin: 9px 0 0;
  color: var(--qt-text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 13px;
  line-height: 1.6;
}

.qt-arc-list {
  display: grid;
  gap: 10px;
  margin-top: 26px;
}

.qt-arc {
  display: grid;
  grid-template-columns: 90px 1fr auto;
  gap: 18px;
  align-items: center;
  padding: 18px 20px;
  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 7px;
}

.qt-arc-number {
  color: var(--qt-gold);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.qt-arc-copy strong {
  display: block;
  color: var(--qt-heading);
  font-size: 16px;
}

.qt-arc-copy span {
  display: block;
  margin-top: 5px;
  color: var(--qt-text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 13px;
}

.qt-arc-status {
  color: var(--qt-text-muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

/* =========================================================
   ABOUT: BACKGROUND / STORY
   ========================================================= */

.qt-about-background {
  display: grid;
  grid-template-columns: minmax(0, 1.28fr) minmax(260px, 0.72fr);
  gap: 34px;
  align-items: start;
  margin-top: 24px;
}

.qt-about-background-copy p {
  margin: 0 0 1.35em;
}

.qt-memory-fragments {
  padding: 22px;
  background: var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 8px;
}

.qt-memory-fragments h3 {
  margin: 0 0 16px;
  color: var(--qt-gold);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.qt-memory-fragments ul {
  margin: 0;
  padding-left: 18px;
  color: var(--qt-text-muted);
}

.qt-memory-fragments li {
  margin: 10px 0;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 14px;
  line-height: 1.55;
}

/* =========================================================
   TABLETOP-STYLE CHARACTER SHEET
   This is a roleplay layer, not WoW combat statistics.
   ========================================================= */

.qt-rpg-sheet {
  margin-top: 26px;
  padding: 26px;
  background:
    linear-gradient(145deg, rgba(102, 127, 140, 0.07), transparent 48%),
    var(--qt-surface);
  border: 1px solid var(--qt-border);
  border-radius: 10px;
}

.qt-rpg-disclaimer {
  margin: 0 0 22px !important;
  color: var(--qt-text-muted) !important;
  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif !important;
  font-size: 11px !important;
  line-height: 1.6 !important;
}

.qt-rpg-identity {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.qt-rpg-field {
  padding: 13px 14px;
  background: rgba(255, 255, 255, 0.018);
  border: 1px solid var(--qt-border);
  border-radius: 6px;
}

.qt-rpg-field span {
  display: block;
  color: var(--qt-text-muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.qt-rpg-field strong {
  display: block;
  margin-top: 7px;
  color: var(--qt-heading);
  font-size: 13px;
  line-height: 1.35;
}

.qt-ability-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 9px;
  margin-top: 18px;
}

.qt-ability {
  padding: 16px 8px;
  text-align: center;
  background: #0b0e11;
  border: 1px solid var(--qt-border);
  border-radius: 7px;
}

.qt-ability-name {
  display: block;
  color: var(--qt-text-muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.qt-ability-score {
  display: block;
  margin-top: 6px;
  color: var(--qt-heading);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 28px;
  line-height: 1;
}

.qt-ability-mod {
  display: block;
  margin-top: 6px;
  color: var(--qt-gold);
  font-size: 10px;
  font-weight: 700;
}

.qt-rpg-columns {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 18px;
}

.qt-rpg-panel {
  padding: 18px;
  background: rgba(255, 255, 255, 0.018);
  border: 1px solid var(--qt-border);
  border-radius: 7px;
}

.qt-rpg-panel h3 {
  margin: 0 0 13px;
  color: var(--qt-gold);
  font-size: 9px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.qt-rpg-panel ul {
  margin: 0;
  padding-left: 17px;
}

.qt-rpg-panel li {
  margin: 8px 0;
  color: var(--qt-text-muted);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 13px;
  line-height: 1.5;
}

.qt-rpg-panel strong {
  color: var(--qt-heading);
}

@media screen and (max-width: 900px) {
  .qt-world-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .qt-about-background {
    grid-template-columns: 1fr;
  }

  .qt-rpg-identity {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .qt-ability-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .qt-rpg-columns {
    grid-template-columns: 1fr;
  }
}

@media screen and (max-width: 700px) {
  .qt-main-nav a {
    flex: 1 1 30%;
  }

  .qt-section-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }

  .qt-journey-hero {
    padding: 28px 22px;
  }

  .qt-journey-current-banner {
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .qt-world-grid {
    grid-template-columns: 1fr;
  }

  .qt-arc {
    grid-template-columns: 1fr;
    gap: 7px;
  }
}

@media screen and (max-width: 520px) {
  .qt-rpg-identity,
  .qt-ability-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}



/* =========================================================
   QUESTTELLER v0.7
   Typography, accessibility, archive repair and responsive UI
   This final layer intentionally overrides earlier incremental rules.
   ========================================================= */

:root {
  --qt-font-display: "Cinzel", Georgia, "Times New Roman", serif;
  --qt-font-reading: "Source Serif 4", Georgia, "Times New Roman", serif;
  --qt-font-ui: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

/* ---------- Resilient global sizing ---------- */

html,
body {
  width: 100%;
  max-width: 100%;
}

body {
  overflow-x: hidden;
  font-family: var(--qt-font-ui);
}

img,
svg,
video,
canvas,
iframe,
embed,
object {
  max-width: 100%;
}

.qt-header-inner,
.page_body .centered,
.centered-bottom,
.qt-single-post,
.qt-page-post,
.qt-chapter-reading,
.qt-journey-page,
.qt-about-page {
  min-width: 0;
}

.qt-journey-overview-grid > *,
.qt-home-about > *,
.qt-about-hero > *,
.qt-about-background > *,
.qt-chapter-card > *,
.qt-world-grid > *,
.qt-rpg-identity > *,
.qt-ability-grid > *,
.qt-rpg-columns > * {
  min-width: 0;
}

/* ---------- Typography ---------- */

.post-body,
.qt-chapter-reading .post-body,
.qt-featured-summary,
.qt-chapter-card-summary,
.qt-journey-overview-copy p,
.qt-home-about-copy p,
.qt-chronicles-hero p,
.qt-about-lede,
.qt-roadmap-copy span,
.qt-journey-hero p,
.qt-journey-section > p,
.qt-world-card p,
.qt-arc-copy span,
.qt-memory-fragments li,
.qt-rpg-panel li,
.qt-chapter-nav-current,
.qt-quote {
  font-family: var(--qt-font-reading);
}

.qt-brand-name,
.qt-featured-title,
.qt-chapter-card-title,
body.item-view .qt-chapter-header .post-title,
.qt-chapter-reading h2,
.qt-page-header .post-title,
.qt-about-name,
.qt-about-section h2,
.qt-journey-overview-copy h2,
.qt-home-explore h2,
.qt-home-about h2,
.qt-chronicles-hero h1,
.qt-journey-hero h2,
.qt-journey-section h2 {
  font-family: var(--qt-font-display);
}

.qt-chapter-reading .post-body > p:first-of-type::first-letter {
  font-family: var(--qt-font-display);
}

/* Keep small UI text crisp and compact. */
.qt-featured-kicker,
.qt-chapter-card-kicker,
.qt-section-kicker,
.qt-chapter-kicker,
.qt-chapter-meta,
.qt-location,
.qt-art figcaption,
.qt-primary-link,
.qt-secondary-link,
.qt-main-nav,
.qt-header-search,
.qt-chapter-nav-direction,
.qt-chapter-nav-home,
.qt-chapter-nav-kicker,
.qt-journey-location,
.qt-journey-stat-label,
.qt-world-state,
.qt-arc-number,
.qt-arc-status,
.qt-rpg-disclaimer,
.qt-rpg-field span,
.qt-ability-name,
.qt-rpg-panel h3 {
  font-family: var(--qt-font-ui);
}

/* ---------- Correct chapter closing utility ---------- */

.qt-chapter-closing {
  text-align: center;
}

/* ---------- Archive post count ---------- */

.BlogArchive .post-count {
  float: none;
  display: inline-block;
  margin-left: 0.35em;
  margin-right: 0;
  color: var(--qt-text-muted);
}

.BlogArchive .post-count::before {
  content: "(";
}

.BlogArchive .post-count::after {
  content: ")";
}

/* ---------- Accessible focus treatment ---------- */

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
summary:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--qt-gold);
  outline-offset: 4px;
}

.qt-visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* ---------- Custom header search ---------- */

.qt-header-search {
  display: flex;
  align-items: center;
  flex: 0 1 230px;
  min-width: 180px;
  height: 42px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.025);
  border: 1px solid var(--qt-border);
  border-radius: 999px;
  transition: border-color 160ms ease, background-color 160ms ease;
}

.qt-header-search:focus-within {
  background: var(--qt-surface-raised);
  border-color: rgba(197, 155, 82, 0.58);
}

.qt-header-search input {
  min-width: 0;
  flex: 1 1 auto;
  height: 100%;
  padding: 0 4px 0 15px;
  background: transparent;
  border: 0;
  outline: 0;
  color: var(--qt-heading);
  font-family: var(--qt-font-ui);
  font-size: 13px;
}

.qt-header-search input::placeholder {
  color: var(--qt-text-muted);
  opacity: 0.8;
}

.qt-header-search button {
  flex: 0 0 auto;
  height: 100%;
  padding: 0 14px;
  background: transparent;
  border: 0;
  border-left: 1px solid var(--qt-border);
  color: var(--qt-gold);
  font-family: var(--qt-font-ui);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.qt-header-search button:hover {
  background: rgba(197, 155, 82, 0.08);
  color: var(--qt-heading);
}

/* ---------- General responsive primitives ---------- */

.qt-main-nav a,
.qt-primary-link,
.qt-secondary-link,
.qt-read-chapter,
.qt-chapter-card-link,
.qt-chapter-nav-card,
.qt-chapter-nav-home,
.qt-header-search button {
  touch-action: manipulation;
}

.qt-main-nav a {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.qt-featured-image img,
.qt-chapter-card-image img,
.qt-home-about-art img,
.qt-about-portrait img,
.qt-art img {
  max-width: 100%;
}

/* ---------- Large tablets / small laptops ---------- */

@media screen and (max-width: 1100px) {
  .page_body .centered {
    padding-left: 20px;
    padding-right: 20px;
  }

  .qt-header-inner {
    flex-wrap: wrap;
    gap: 14px 20px;
    padding-left: 20px;
    padding-right: 20px;
  }

  .qt-brand {
    flex: 1 1 auto;
  }

  .qt-main-nav {
    order: 3;
    width: 100%;
    justify-content: center;
    border-top: 1px solid var(--qt-border);
    padding-top: 8px;
  }

  .qt-header-search {
    flex: 0 1 250px;
  }

  .qt-featured-content {
    padding: 34px 36px 38px;
  }

  .qt-journey-overview-grid {
    grid-template-columns: minmax(0, 1.2fr) minmax(260px, 0.8fr);
    gap: 26px;
  }

  .qt-home-about,
  .qt-about-hero {
    gap: 28px;
  }

  .qt-chapter-card {
    grid-template-columns: minmax(230px, 42%) minmax(0, 1fr);
  }
}

/* ---------- Portrait tablets ---------- */

@media screen and (max-width: 900px) {
  .qt-journey-overview-grid,
  .qt-home-about,
  .qt-about-hero,
  .qt-about-background {
    grid-template-columns: 1fr;
  }

  .qt-home-about-art,
  .qt-about-portrait {
    max-width: 680px;
    margin-left: auto;
    margin-right: auto;
  }

  .qt-about-portrait img {
    aspect-ratio: 16 / 10;
    object-position: 50% 20%;
  }

  .qt-journey-stats,
  .qt-character-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .qt-world-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .qt-rpg-identity {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .qt-ability-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .qt-rpg-columns {
    grid-template-columns: 1fr;
  }

  .qt-footer-content,
  #footer .qt-footer-content {
    flex-wrap: wrap;
  }
}

/* ---------- Phones / compact tablets ---------- */

@media screen and (max-width: 700px) {
  .page_body .centered {
    padding: 10px 10px 48px;
  }

  .centered-bottom {
    padding-left: 0;
    padding-right: 0;
  }

  .qt-header-inner {
    padding: 12px 14px;
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .qt-brand {
    justify-content: center;
    width: 100%;
  }

  .qt-main-nav {
    order: 2;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    width: 100%;
    gap: 4px;
    padding-top: 8px;
  }

  .qt-main-nav a {
    width: 100%;
    min-width: 0;
    padding: 10px 5px;
    font-size: 10px;
    line-height: 1.2;
    text-align: center;
  }

  .qt-header-search {
    order: 3;
    width: 100%;
    min-width: 0;
    flex-basis: 42px;
  }

  .qt-featured-chapter,
  .qt-journey-overview,
  .qt-home-about,
  .qt-chronicles-hero,
  .qt-journey-hero,
  .qt-rpg-sheet {
    border-radius: 8px;
  }

  .qt-featured-content {
    padding: 26px 20px 30px;
  }

  .qt-featured-title {
    font-size: clamp(1.9rem, 9vw, 2.7rem);
    line-height: 1.05;
  }

  .qt-chapter-card {
    grid-template-columns: 1fr;
  }

  .qt-chapter-card-image,
  .qt-chapter-card-image img {
    min-height: 0;
  }

  .qt-chapter-card-image img {
    aspect-ratio: 16 / 9;
    object-fit: cover;
  }

  .qt-chapter-card-content {
    padding: 22px 20px 26px;
  }

  body.item-view .qt-chapter-header,
  .qt-page-header {
    padding-left: 14px;
    padding-right: 14px;
  }

  body.item-view .qt-chapter-header .post-title,
  body.item-view .qt-page-header .post-title {
    font-size: clamp(2.15rem, 11vw, 3.7rem);
    line-height: 1;
    letter-spacing: -0.035em;
    overflow-wrap: anywhere;
  }

  .qt-chapter-reading .post-body {
    padding-left: 16px;
    padding-right: 16px;
    font-size: 17px;
    line-height: 1.78;
  }

  .qt-chapter-reading h2 {
    font-size: clamp(1.55rem, 7vw, 2.15rem);
  }

  .qt-art,
  .qt-art-wide,
  .qt-art-full {
    width: calc(100vw - 24px);
    max-width: calc(100vw - 24px);
  }

  .qt-quote {
    margin-left: 0;
    margin-right: 0;
    padding: 24px 18px;
    font-size: clamp(1.25rem, 6vw, 1.75rem);
  }

  .qt-divider::before,
  .qt-divider::after {
    width: min(72px, 22vw);
  }

  .qt-chapter-nav {
    width: calc(100% - 32px);
  }

  .qt-chapter-nav-grid {
    grid-template-columns: 1fr;
  }

  .qt-chapter-nav-prev,
  .qt-chapter-nav-next {
    text-align: left;
  }

  .qt-chapter-nav-home {
    order: 3;
    justify-self: center;
  }

  .qt-journey-overview,
  .qt-chronicles-hero,
  .qt-journey-hero {
    padding: 24px 20px;
  }

  .qt-journey-current-banner,
  .qt-arc,
  .qt-roadmap-item {
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .qt-explore-grid,
  .qt-world-grid {
    grid-template-columns: 1fr;
  }

  .qt-home-about {
    padding: 18px;
  }

  .qt-home-about-art img,
  .qt-about-portrait img {
    aspect-ratio: 16 / 9;
  }

  .qt-rpg-sheet {
    padding: 20px 16px;
  }

  body.item-view #comments,
  body.item-view .qt-chapter-footer {
    width: calc(100% - 32px);
  }

  #footer {
    width: calc(100% - 20px);
    margin-top: 44px;
    padding-left: 10px;
    padding-right: 10px;
  }

  #footer .qt-footer-content {
    flex-direction: column;
    align-items: center;
    text-align: center;
  }

  .qt-footer-brand,
  .qt-footer-platform {
    text-align: center;
  }
}

/* ---------- Small phones ---------- */

@media screen and (max-width: 480px) {
  .qt-brand-mark.qt-brand-portrait {
    width: 46px;
    height: 46px;
    flex-basis: 46px;
  }

  .qt-brand-name {
    font-size: 18px;
  }

  .qt-brand-tagline {
    font-size: 9px;
  }

  .qt-main-nav {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .qt-header-search input {
    font-size: 16px; /* prevents iOS zoom on focus */
  }

  .qt-journey-stats,
  .qt-character-grid,
  .qt-rpg-identity,
  .qt-ability-grid {
    grid-template-columns: 1fr;
  }

  .qt-journey-actions {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .qt-primary-link,
  .qt-secondary-link {
    min-height: 44px;
    justify-content: center;
    text-align: center;
  }

  .qt-featured-content,
  .qt-chapter-card-content {
    padding-left: 18px;
    padding-right: 18px;
  }

  .qt-about-name {
    font-size: clamp(2.2rem, 13vw, 3.5rem);
  }

  .qt-about-lede {
    font-size: 17px;
  }

  .qt-level-card,
  .qt-memory-fragments,
  .qt-rpg-panel {
    padding-left: 16px;
    padding-right: 16px;
  }
}

/* ---------- Reduced motion ---------- */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto !important;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page,
body#layout .sidebar_top,
body#layout .sidebar_bottom {
  display: inline-block;
  left: inherit;
  position: relative;
  vertical-align: top;
}
body#layout .page {
  float: right;
  margin-left: 20px;
  width: 55%;
}
body#layout .sidebar-container {
  float: right;
  width: 40%;
}
body#layout .hamburger-menu {
  display: none;
}
